; DOS U preset: King's Quest I (SCI remake), Korean UTF-8 translation.
; Two faces, picked by the game's font id:
;   body - font 300, the message boxes and narration: KO2350B.SVF (Gowun
;          Batang Bold, 17 px, 2 bpp, ASCII + ksx1001-nohanja: 2350 Hangul +
;          KS X 1001 symbols);
;   UI   - everything else (font 0: status line, menu bar, parser line;
;          font 4: the title menu's buttons; any other id): KO2350G.SVF
;          (NanumGothic-Bold, 16 px, 2 bpp, same charset).
; Shared fonts (common2350-brief, 2026-09-29): KO2350G.SVF/KO2350B.SVF
; replace the old KOCP949.SVF/KOBATANG.SVF (full 11172-syllable cp949) here;
; the coverage gate found KQ1's translation needs nothing outside the 2350.
; Both are baked on one baseline in a 16x16 cell (bake-dos-fonts.sh,
; --clip-cell): align=cell puts them on the game's 16-row line with no
; offset and no ink above or below it. The 16 px KO2350.SVF no longer backs
; them up: its other baseline would make the face chain 18 rows and move
; every glyph up a row; KQ1's text needs none of the symbols it held.
; Characters neither face has draw U+25A1. rgb_rendering=true
; (scummvm.ini) is what makes this render truecolor/antialiased; alpha=
; below is documentation only, SCI ignores it (spec 4.5).
[hires]
scale=2
alpha=true
face=ui
missing=u+25a1
align=cell

[fonts]
ui=KO2350G.SVF
body=KO2350B.SVF

[latin]
mode=proportional
metrics=font

[font.300]
face=body
